import React, { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

const TutorRegister = () => {
  const [name, setName] = useState("");
  const [experience, setExperience] = useState("");
  const [credentials, setCredentials] = useState("");
  const [expertiseCourses, setExpertiseCourses] = useState("");
  const [address, setAddress] = useState("");
  const [contactInfo, setContactInfo] = useState("");
  const [calendly, setCalendly] = useState("");
  const [resume, setResume] = useState(null);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append("name", name);
    formData.append("experience", experience);
    formData.append("credentials", credentials);
    formData.append("expertise_courses", expertiseCourses);
    formData.append("address", address);
    formData.append("contact_info", contactInfo);
    formData.append("calendly_link", calendly);
    formData.append("resume", resume);

    try {
      const token = localStorage.getItem("token");
      await axios.post("http://localhost:8000/api/register-tutor", formData, {
        headers: {
          "Content-Type": "multipart/form-data",
          Authorization: `Bearer ${token}`,
        },
      });
      alert("Tutor registered successfully!");
      navigate("/dashboard");
    } catch (err) {
      console.error(err);
      alert("Registration failed");
    }
  };

  return (
    <div className="max-w-md mx-auto mt-10 p-6 bg-white shadow-md rounded-md">
      <h2 className="text-xl font-bold mb-4">Register as Tutor</h2>
      <form onSubmit={handleSubmit}>
        <input type="text" value={name} onChange={(e) => setName(e.target.value)} placeholder="Name" required className="input" />
        <input type="text" value={experience} onChange={(e) => setExperience(e.target.value)} placeholder="Experience" required className="input" />
        <input type="text" value={credentials} onChange={(e) => setCredentials(e.target.value)} placeholder="Credentials" required className="input" />
        <input type="text" value={expertiseCourses} onChange={(e) => setExpertiseCourses(e.target.value)} placeholder="Expertise Courses" required className="input" />
        <input type="text" value={address} onChange={(e) => setAddress(e.target.value)} placeholder="Address" required className="input" />
        <input type="text" value={contactInfo} onChange={(e) => setContactInfo(e.target.value)} placeholder="Contact Info" required className="input" />
        <input type="text" value={calendly} onChange={(e) => setCalendly(e.target.value)} placeholder="Calendly Link" className="input" />
        <input type="file" onChange={(e) => setResume(e.target.files[0])} required className="input" />
        <button type="submit" className="btn-primary mt-4">Register</button>
      </form>
    </div>
  );
};

export default TutorRegister;
